SELECT * FROM (SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'Q:'||request_id event_id,'Receiving Request Submitted' activity,submitted_at timestamp,request_id source_key FROM receiving_request WHERE submitted_at IS NOT NULL AND (1=1)) e JOIN receiving_request s ON s.request_id=e.source_key WHERE s.request_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
